def model(dbt, session):
    dbt.config(materialized="table")
    threshold = dbt.config.get("loyal_threshold")
    target_name = dbt.config.get("target_name")
    customers = dbt.ref("dim_customers")
    return customers.filter(f"lifetime_value >= {threshold}").aggregate(
        f"'{target_name}' as target_name, {threshold} as threshold, count(*) as n_customers"
    )

def model(dbt, session):
    dbt.config(materialized="incremental", unique_key="order_id")

    orders = dbt.ref("stg_jaffle_shop__orders")

    if dbt.is_incremental:
        # only the rows loaded after the newest row already in the table
        max_loaded = session.sql(f"select max(loaded_at) from {dbt.this}").fetchone()[0]
        orders = orders.filter(f"loaded_at > '{max_loaded}'")

    return orders.select("order_id, status, loaded_at")
